pages.source:
Page(name: "Password reset", route: Route(path: "/reset-password"))

Build(
  Scaffold(
    appBar: MorningCrateHeader(),
    body: ScrollView(label: "Password reset", child: Column(gap: Space.md, padding: Insets(y: 12), children: [Column(gap: Space.lg, padding: Insets(x: 18, y: 8), children: [
    Text(child: "Account", size: FontSize.xs, weight: FontWeight.bold, letterSpacing: 2, color: Color.textMuted), Text(child: "Forgotten your password?", size: FontSize.xxl, weight: FontWeight.bold, lineHeight: 1.15), Text(child: "Enter your email; a link to choose a new one follows.", size: FontSize.sm, color: Color.textMuted, fontStyle: FontStyle.italic), Divider(), Form(id: "resetPassword", onSubmit: ResetPreviewPassword(), child: Column(gap: Space.md, children: [TextField(name: "email", label: "Your email", type: InputType.email, required: true, background: Color.surface, border: Border(width: 1, color: Color.border), radius: Radius.lg), SubmitButton(label: "Send the link", fullWidth: true)])), Button(label: "Back to the menu", style: ButtonStyle.ghost, icon: Icons.chevronLeft, onTap: Navigate(to: Route.menu))
  ])])),
  )
)
